        "type": "object",
        "properties": {
          "query": {
            "type": "string"
          }
        },
        "required": [
          "query"
        ]
      }
    },
    {
      "name": "get_weather",
      "description": "Get the current weather for a city.",
      "defer_loading": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "city": {
            "type": "string"
          }
        },
        "required": [
          "city"
        ]
      }
    }
  ],
  "messages": [
    {
      "role": "user",
      "content": "What's the weather in Tokyo?"
    },
    {
      "role": "assistant",
      "content": [
        {
          "type": "tool_use",
          "id": "toolu_find_1",
          "name": "find_tools",
          "input": {
            "query": "weather"
          }
        }
      ]
    },
    {
      "role": "user",
      "content": [
        {
          "type": "tool_result",
          "tool_use_id": "toolu_find_1",
          "content": [
            {
              "type": "text",
              "text": "Found 1 tool"
            },
            {
              "type": "tool_reference",
              "tool_name": "get_weather"
            }
          ]
        }
      ]
    }
  ]
}

